#!/usr/bin/env bash
# Path: plowinf/tools/plowinf_viewer.sh
# Purpose: Real-time viewer & tracker for files generated by plowinf.
# Uses jq to parse and format JSON audit journals, work products, and queues.
# Max Column: 80 (comments) / 120 (code)

set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
JOURNAL="${REPO_ROOT}/logs/forensics/audit_journal.jsonl"
HEARTBEAT="${REPO_ROOT}/logs/heartbeat/plowinf.json"
QUEUE_DIR="${REPO_ROOT}/records/queue"
WORK_PRODUCTS_DIR="${REPO_ROOT}/workspace/work_products"

# ANSI Color Codes
CYAN="\033[1;36m"
GREEN="\033[1;32m"
YELLOW="\033[1;33m"
BLUE="\033[1;34m"
MAGENTA="\033[1;35m"
BOLD="\033[1m"
RESET="\033[0m"

check_dependencies() {
    if ! command -v jq >/dev/null 2>&1; then
        echo -e "${YELLOW}[!] Warning: 'jq' not found. Installing jq will enable advanced formatting.${RESET}" >&2
    fi
}

show_header() {
    echo -e "${CYAN}========================================================================================${RESET}"
    echo -e "${BOLD}                     PLOWINF - ARTIFACT & INFERENCE ACTIVITY VIEWER                     ${RESET}"
    echo -e "${CYAN}========================================================================================${RESET}"
}

show_queue_and_heartbeat() {
    echo -e "\n${BOLD}[System & Queue Status]${RESET}"
    if [ -f "${HEARTBEAT}" ]; then
        jq -r '"  Daemon Status : \(.status) (PID \(.pid), RSS \(.rss_mb) MB, Host: \(.hostname // "localhost"))
  Backend Engine: \(.active_backend)
  Processed     : \(.processed_tasks) tasks | Failed: \(.failed_tasks) tasks"' "${HEARTBEAT}"
    else
        echo "  Heartbeat: No active daemon heartbeat found."
    fi

    local in_cnt proc_cnt done_cnt fail_cnt
    count_tasks() {
        local dir="$1"
        if [ -d "$dir" ]; then
            find "$dir" -name 'task-*.json' | wc -l
        else
            echo 0
        fi
    }
    in_cnt=$(count_tasks "${QUEUE_DIR}/incoming")
    proc_cnt=$(count_tasks "${QUEUE_DIR}/processing")
    done_cnt=$(count_tasks "${QUEUE_DIR}/done")
    fail_cnt=$(count_tasks "${QUEUE_DIR}/failed")

    echo -e "  Queue Counts  : ${YELLOW}Incoming: ${in_cnt}${RESET} | " \
        "${BLUE}Processing: ${proc_cnt}${RESET} | " \
        "${GREEN}Done: ${done_cnt}${RESET} | " \
        "${MAGENTA}Failed: ${fail_cnt}${RESET}"
}

show_work_products_table() {
    echo -e "\n${BOLD}[Generated Work Products & Executions (Parsed via jq)]${RESET}"
    if [ ! -f "${JOURNAL}" ]; then
        echo "  No audit journal found at ${JOURNAL}."
        return
    fi

    printf "  %-19s | %-16s | %-9s | %-7s | %-8s | %s\n" \
        "Timestamp (UTC)" "Task ID" "Action" "Status" "Duration" "Target & Work Product"
    echo "  --------------------+------------------+-----------+---------+----------+---------------------------------"

    jq -r 'select(.phase == "INFERENCE_EXECUTION") | 
        "\(.timestamp_utc[:19]) | \(.task_id) | \(.action) | \(.status) | " +
        "\((.duration_ms / 1000 | tostring)[:5])s | " +
        "\(.target.path // "N/A") -> \(.work_product_path // "none")"' \
        "${JOURNAL}" | while IFS='|' read -r ts tid act st dur dest; do
            st_trimmed="$(echo "${st}" | xargs)"
            color="${GREEN}"
            if [ "${st_trimmed}" != "SUCCESS" ]; then
                color="${YELLOW}"
            fi
            printf "  %-19s | %-16s | %-9s | ${color}%-7s${RESET} | %-8s | %s\n" \
                "${ts}" "${tid}" "${act}" "${st_trimmed}" "${dur}" "${dest}"
    done
}

show_latest_detail() {
    echo -e "\n${BOLD}[Latest Completed Work Product Detail]${RESET}"
    if [ ! -f "${JOURNAL}" ]; then
        echo "  No audit journal records."
        return
    fi

    local latest_record
    latest_record=$(jq -s 'map(select(.phase == "INFERENCE_EXECUTION")) | last' "${JOURNAL}")
    if [ -z "${latest_record}" ] || [ "${latest_record}" = "null" ]; then
        echo "  No inference records found."
        return
    fi

    echo "${latest_record}" | jq '{
        task_id: .task_id,
        action: .action,
        status: .status,
        duration_seconds: (.duration_ms / 1000),
        target_file: .target.path,
        target_sha256: .target.sha256,
        prompt_preview: (.prompt.text[:120] + "..."),
        work_product_file: .work_product_path,
        output_sha256: .response.sha256
    }'

    local wp_path
    wp_path=$(echo "${latest_record}" | jq -r '.work_product_path // empty')
    if [ -n "${wp_path}" ] && [ -f "${wp_path}" ]; then
        echo -e "\n${BOLD}[Work Product Preview (${wp_path})]:${RESET}"
        head -n 25 "${wp_path}"
        echo -e "${CYAN}... (view full file at ${wp_path})${RESET}"
    fi
}

show_task_detail() {
    local target_task="$1"
    echo -e "\n${BOLD}[Task Detail: ${target_task}]${RESET}"
    if [ ! -f "${JOURNAL}" ]; then
        echo "  No journal found."
        return
    fi

    local record
    record=$(jq --arg t "${target_task}" \
        'select(.task_id == $t and .phase == "INFERENCE_EXECUTION")' "${JOURNAL}" | tail -n 1)
    if [ -z "${record}" ]; then
        echo "  Task ${target_task} not found in journal."
        return
    fi

    echo "${record}" | jq .
}

follow_stream() {
    echo -e "\n${BOLD}[Following Real-Time Forensic Stream (Ctrl+C to stop)]${RESET}\n"
    tail -f -n 5 "${JOURNAL}" | while read -r line; do
        if echo "${line}" | jq -e 'select(.phase == "INFERENCE_EXECUTION")' >/dev/null 2>&1; then
            echo "${line}" | jq -r '"[\(.timestamp_utc[:19])] [INFERENCE] Task: \(.task_id) | " +
                "Action: \(.action) | Status: \(.status) | Duration: \((.duration_ms / 1000 | tostring)[:5])s\n" +
                "  Target       : \(.target.path // "N/A")\n" +
                "  Output SHA256: \(.response.sha256)\n" +
                "  Work Product : \(.work_product_path // "N/A")"'
            echo "----------------------------------------------------------------------------------------"
        elif echo "${line}" | jq -e 'select(.phase != null)' >/dev/null 2>&1; then
            echo "${line}" | jq -r '"[\(.timestamp_utc[:19])] [\(.phase)] Task: \(.task_id) | " +
                "Action: \(.action) | Telemetry: RSS \(.telemetry.rss_mb) MB"'
        fi
    done
}

# CLI Argument Router
check_dependencies

case "${1:-summary}" in
    summary|--summary|-s)
        show_header
        show_queue_and_heartbeat
        show_work_products_table
        show_latest_detail
        ;;
    latest|--latest|-l)
        show_header
        show_latest_detail
        ;;
    follow|--follow|-f)
        show_header
        show_queue_and_heartbeat
        follow_stream
        ;;
    task|--task|-t)
        if [ -z "${2:-}" ]; then
            echo "Usage: $0 --task <task_id>"
            exit 1
        fi
        show_header
        show_task_detail "$2"
        ;;
    products|--products|-p)
        show_header
        echo -e "\n${BOLD}[All Generated Work Product Files]${RESET}"
        find "${WORK_PRODUCTS_DIR}" -type f -name '*.md' | sort | while read -r f; do
            sz=$(du -h "${f}" | cut -f1)
            lines=$(wc -l < "${f}")
            rel="${f#${REPO_ROOT}/}"
            printf "  %-8s (%4d lines)  %s\n" "${sz}" "${lines}" "${rel}"
        done
        ;;
    help|--help|-h)
        show_header
        echo "Usage: $0 [COMMAND]"
        echo ""
        echo "Commands:"
        echo "  summary (default) - Display complete queue, system status, and work product table"
        echo "  latest            - Show latest generated work product and JSON audit record via jq"
        echo "  follow, -f        - Stream live completed tasks and audit logs in real time"
        echo "  task <task_id>    - Pretty-print full JSON audit trail and response for a task"
        echo "  products, -p      - List all generated work product markdown files on disk"
        echo "  help              - Display this help message"
        ;;
    *)
        echo "Unknown option: $1 (run '$0 help' for usage)"
        exit 1
        ;;
esac

# end of file: plowinf/tools/plowinf_viewer.sh
